from collections import Counter,defaultdict,deque

def comp_info(g):
 h,w=len(g),len(g[0]);bg=Counter(x for row in g for x in row).most_common(1)[0][0]; seen=set(); info=[]
 for r in range(h):
  for c in range(w):
   co=g[r][c]
   if co==bg or (r,c) in seen:continue
   q=deque([(r,c)]);seen.add((r,c));cells=[]
   while q:
    x,y=q.popleft();cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]==co: seen.add((a,b));q.append((a,b))
   bounds=(min(x for x,y in cells),max(x for x,y in cells),min(y for x,y in cells),max(y for x,y in cells))
   touch=any(x in (0,h-1) or y in (0,w-1) for x,y in cells)
   info.append((co,len(cells),bounds,touch,tuple(cells)))
 return bg,info
